# The starter crypt, re-authored to the modular mossy kit's scale. The old
# hand-built maze was one tile wide, so the 4-unit kit pieces could not tile it
# and their relief jammed into the corridors. This version is built from wide
# open halls (which the kit clads cleanly) joined by short doorways, with pillar
# blocks for crypt character. 1=wall, 0=open floor.
map DUNGEON
size 24 24
tileset 10
music 0
area crypt
# the modular crypt kit wants roughly three-unit ceilings, so the base sector
# is taller than the old flat default; the central gallery is taller still and
# its floor drops half a unit for a grand sunken hall
sector 0 0 48
sector 1 -8 64
walls
111111111111111111111111
100000000000000000000001
100000000000000000000001
100000011000000110000001
100000011000000110000001
100000000000000000000001
111001111110011111100111
100000000000000000000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
111001111110011111100111
100000000000000000000001
100000000000000000000001
100000011000000110000001
100000011000000110000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
100000000000000000000001
111111111111111111111111
end
# the central five-row hall is the sunken grand gallery
fill 1 1 7 22 11
marker start 2 2 E
marker back 4 2 S
marker grotto 3 21 E
portal 4 1 TOWN gate
portal 8 10 CATACOMB start
portal 15 10 MAZE start
portal 20 1 INFERNAL start
portal 2 21 GROTTO start
npc 22 22 SHRINE Shrine NPC_SHRINE2
trap 5 9 6 12
trap 18 9 8 13
trap 12 18 7 13
# the torch-lit sunken gallery reads brighter than the dim side halls
trigger ambient 96 - 4 7 19 7 19 11 4 11
# a one-time line when the party first descends into the gallery
trigger event 0 SAWGALLERY 4 7 19 7 19 11 4 11
eventmsg SAWGALLERY A VAST SUNKEN GALLERY OPENS BELOW, RIBBED IN OLD STONE.
moonwell 13 9
torch 3 8
torch 20 8
brazier 5 18
prop 11 9 BARREL
prop 12 9 BARREL 45
loot 11 9 120 ELIXIR 1
loot 12 9 90 SILVER 1
prop 21 22 BARREL
loot 21 22 0 WARDSHLD 1
